package com.clavis.reader;
public class ArticleContentChecks {
 static int checks;static void check(boolean value,String name){checks++;if(!value)throw new AssertionError(name);}
 public static void main(String[] args)throws Exception{String prose="This is the actual article paragraph, with punctuation and enough words to establish the main reading content. ";String html="<html><head><meta property='og:title' content='A clear headline'></head><body><header>Website masthead</header><nav>Menu links</nav><main><article><h1>A clear headline</h1><div class='article-body'><p>"+prose.repeat(3)+"</p><figure><img data-src='../photos/hero.jpg'><figcaption>Photo caption</figcaption></figure><h2>Second section</h2><p>More article text, naturally separated.</p><ul><li>First point</li><li>Second point</li></ul><div hidden><p>Hidden text</p></div><p style='display: none'>Invisible text</p><aside>Sponsored message</aside><div class='related'><p>Related story</p></div><div class='cookie-banner'>Accept cookies</div><script>tracker()</script><img width='1' height='1' src='/pixel.gif'></div></article></main><footer>Legal navigation</footer></body></html>";ArticleContent article=ArticleContent.extract(html,"https://example.com/news/story",false);String text=article.blocks.stream().map(b->b.value).collect(java.util.stream.Collectors.joining("\n"));check(article.title.equals("A clear headline"),"Headline");check(text.contains(prose.trim()),"Article prose retained");for(String removed:new String[]{"masthead","Menu links","Hidden text","Invisible text","Sponsored message","Related story","Accept cookies","tracker()","Legal navigation","pixel.gif"})check(!text.contains(removed),"Remove "+removed);check(article.blocks.stream().anyMatch(b->b.kind.equals("img")&&b.value.equals("https://example.com/photos/hero.jpg")),"Lazy relative image");check(article.blocks.stream().anyMatch(b->b.kind.equals("caption")&&b.value.equals("Photo caption")),"Image caption");check(article.blocks.stream().anyMatch(b->b.kind.equals("heading")&&b.value.equals("Second section")),"Section heading");check(article.blocks.stream().filter(b->b.kind.equals("li")).count()==2,"List structure");check(article.blocks.stream().filter(b->b.kind.equals("img")).count()==1,"Tracking image omitted");ArticleContent feed=ArticleContent.extract("<p>Feed content.</p><img src='/image.png'>","https://example.com/feed",true);check(feed.characters>0&&feed.blocks.size()==2,"Feed fallback text and image");ArticleContent responsive=ArticleContent.extract("<p>Text</p><img srcset='/small.jpg 300w, /large.jpg 1200w, /huge.jpg 2400w'>","https://example.com/",true);check(responsive.blocks.stream().anyMatch(b->b.value.endsWith("large.jpg")),"Responsive image choice");check(ArticleContent.url("https://example.com/","javascript:alert(1)").isEmpty(),"Non-web image blocked");String clutter="<article><div class='article-body'><p>"+prose.repeat(4)+"</p><p>Story continues below this ad</p><div class='ad_container'><p>Buy this product</p></div><div class='socialLinks'><a href='https://facebook.com/sharer?u=x'>Share on Facebook</a><a href='https://api.whatsapp.com/send?text=x'>Send to WhatsApp</a></div><p><span>Advertisement</span></p><h2>Also Read</h2><p><a href='/other'>Other article link</a></p><p>"+prose.repeat(2)+"</p><h2>More Premium Stories</h2><div><a href='/another'>Another article</a><p>"+"Unrelated story teaser. ".repeat(10)+"</p></div></div></article>";ArticleContent cleaned=ArticleContent.extract(clutter,"https://example.com/news",false);String cleanedText=cleaned.blocks.stream().map(b->b.value).collect(java.util.stream.Collectors.joining("\n"));for(String removed:new String[]{"Story continues below","Buy this product","Facebook","WhatsApp","Advertisement","Other article link","More Premium Stories","Another article","Unrelated story teaser"})check(!cleanedText.contains(removed),"Real article clutter removed: "+removed);check(cleaned.characters>=prose.length()*5,"Preserve prose after inline related links");ArticleContent discussion=ArticleContent.extract("<article><p>"+prose.repeat(2)+"</p><p>The story explains how advertising affects social media and Facebook users.</p></article>","https://example.com",false);check(discussion.blocks.stream().anyMatch(b->b.value.contains("advertising affects social media")),"Preserve real discussion of ads and social media");ArticleContent trailing=ArticleContent.extract("<meta property='og:image' content='/hero.jpg'><article><div class='article-body'><p>"+prose.repeat(3)+"</p><div><h2>More on this story</h2><p>Other headline</p></div><p>Additional article outside nested section.</p></div></article>","https://example.com/story",false);check(trailing.blocks.stream().noneMatch(b->b.value.contains("Other headline")||b.value.contains("Additional article")),"Nested related section stops entire article");check(trailing.blocks.stream().anyMatch(b->b.kind.equals("img")&&b.value.equals("https://example.com/hero.jpg")),"Main metadata image restored");check(ArticleContent.url("https://example.com/story","").isEmpty(),"Missing image URL does not become article URL");for(String label:new String[]{"AI narration","1x 2x","0.5x 1x 1.5x 2x","This audio is AI generated","This audio was generated using artificial intelligence.","Thank you for your feedback","Thank you for feedback"}){ArticleContent controls=ArticleContent.extract("<article><p>"+prose.repeat(2)+"</p><p>"+label+"</p></article>","https://example.com",false);check(controls.blocks.stream().noneMatch(b->b.value.equals(label)),"Remove narration UI: "+label);}ArticleContent narrator=ArticleContent.extract("<article><p>"+prose.repeat(2)+"</p><div class='audioPlayer'><p>Player status and settings</p><span>1x</span></div><p>Researchers compared AI narration with human narration and collected feedback.</p></article>","https://example.com",false);check(narrator.blocks.stream().noneMatch(b->b.value.contains("Player status")),"Remove whole player widget");check(narrator.blocks.stream().anyMatch(b->b.value.contains("Researchers compared AI narration")),"Keep actual article text about narration");ArticleContent duplicates=ArticleContent.extract("<meta property='og:image' content='https://example.com/photo.jpg?width=1600'><article><p>"+prose.repeat(2)+"</p><img src='/photo.jpg?width=600'><img src='/photo.jpg?width=1200'><img src='/photo-320x200.jpg'><img src='/other-photo.jpg'></article>","https://example.com/story",false);check(duplicates.blocks.stream().filter(b->b.kind.equals("img")).count()==2,"Collapse lead, responsive and resized duplicate images");check(!ArticleContent.imageKey("https://example.com/image?id=1&w=600").equals(ArticleContent.imageKey("https://example.com/image?id=2&w=600")),"Keep distinct image identifiers");check(ArticleContent.imageKey("https://example.com/image?id=1&w=600").equals(ArticleContent.imageKey("https://example.com/image?w=1200&id=1#view")),"Ignore sizing and fragment while retaining identity");ArticleContent express=ArticleContent.extract("<article><p>"+prose.repeat(3)+"</p><div class='translation-toggle-wrap fpuuid-present'><p>AI Narration 1x 2x</p><p>Translation control</p></div><div class='ai-info-backdrop'><div class='ai-info-popup'><h4>AI Translation</h4><p>Translation popup disclaimer text.</p></div></div><div class='feedback-toast'><p>Your feedback has been reported succesfully.</p></div><p>Your feedback have been saved</p><p>AI Translation</p><p>Actual article paragraph after controls.</p></article>","https://indianexpress.com/article/test",false);String expressText=express.blocks.stream().map(b->b.value).collect(java.util.stream.Collectors.joining("\n"));for(String unwanted:new String[]{"AI Narration","Translation control","AI Translation","popup disclaimer","feedback"})check(!expressText.contains(unwanted),"Indian Express UI removed: "+unwanted);check(expressText.contains("Actual article paragraph"),"Keep prose after translation controls");System.out.println(checks+" clean-article extraction checks passed");if(args.length>0){ArticleContent live=ArticleContent.extract(java.nio.file.Files.readString(java.nio.file.Path.of(args[0])),args[1],false);System.out.println("Live article: "+live.characters+" text characters, "+live.blocks.stream().filter(b->b.kind.equals("img")).count()+" images");check(live.characters>1000,"Live full article text");}}
}
